function home(){return `<section class="care-hero"><video class="hero-video" muted playsinline loop preload="metadata" poster="/assets/hero-poster.jpg" aria-hidden="true"><source src="/assets/hero-background.mp4" type="video/mp4"></video><div class="hero-shade" aria-hidden="true"></div><div class="hero-copy"><span class="eyebrow">A trusted diagnostic partner in Ghana</span><h1>A clearer picture of your health.</h1><div class="hero-bottom">${btn('book-appointment','Book a test','blue')}<p>Thoughtful diagnostics, trusted expertise and care for every stage of life.</p><button id="hero-pause" type="button" aria-label="Pause background slideshow" aria-pressed="false">Pause</button></div></div></section><section class="care-intro section"><div class="wrap"><div class="intro-top"><h2>Your wellbeing.<br>At the heart of<br><span>everything we do.</span></h2><div class="intro-side"><span class="eyebrow">Connected around you</span><p>Laboratory testing. DNA. Imaging. Health screening. MMALABS connects the services you need with a clear path to your next step.</p>${link('about','Meet MMALABS <span>↗</span>','textlink')}</div></div><div class="outline-services">${[['Laboratory testing','tests'],['DNA testing','dna-testing'],['Imaging & radiology','radiology'],['Home & office visits','book-appointment'],['Corporate health','corporate-health']].map(s=>link(s[1],s[0]+'<span>↗</span>')).join('')}</div></div></section><section class="care-photo"><img src="/assets/13783.jpg" alt="Laboratory scientist working at a lab bench" width="1000" height="665" loading="lazy"><div class="photo-caption"><span>Sample. Science. Clarity.</span>${link('about','The people behind your answers ↗')}</div></section><section class="values-band" aria-label="Our approach"><div><span>Precision</span><b>+</b><span>Care</span><b>+</b><span>Clarity</span><b>+</b><span>Connection</span><b>+</b><span>Precision</span><b>+</b><span>Care</span><b>+</b></div></section><section class="care-search section"><div class="wrap search-layout"><div><span class="eyebrow">Find your next step</span><h2>What do you<br>need tested?</h2></div><div><div class="searchbox"><input id="hero-search" aria-label="Search laboratory tests" placeholder="Search a test or a health concern"><span>↗</span></div><p>Try blood glucose, cholesterol or DNA.</p>${link('help-me-choose','Not sure where to start? Let us guide you ↗','textlink')}</div><div id="search-results" class="results" aria-live="polite"></div></div></section><section class="screening-story section"><div class="wrap"><div class="section-head"><span class="eyebrow">Nkwafit health screening</span><h2>Make room<br>for your health.</h2><p>Start a proactive conversation about your wellbeing. Explore a screening option and confirm the details with the team.</p></div><div class="screening-options">${[['Men’s health','For him.','Men’s screening'],['Women’s health','For her.','Women’s screening'],['Hypertension care','For the long run.','Hypertension screening']].map((p,i)=>`<article><span class="option-number">0${i+1}</span><div><h3>${p[0]}</h3><p>${p[1]}</p><label><input type="checkbox" data-compare="${i}"> Compare this screening</label></div>${btn('book-appointment?service='+encodeURIComponent(p[2]),'Explore screening','outline')}</article>`).join('')}</div><div id="comparison" aria-live="polite"></div></div></section><section class="dna-feature"><div class="feature-image"><img src="/assets/3747.jpg" alt="Laboratory professional reviewing genetic data" width="1000" height="563" loading="lazy"></div><div class="feature-copy"><span class="eyebrow">DNA Testing Center</span><h2>Personal questions.<br>Scientific answers.</h2><p>Understand your DNA testing options, the consent process and what to expect before sample collection.</p>${btn('dna-testing','Explore DNA testing','blue')}</div></section><section class="department-section section"><div class="wrap"><div class="section-head"><span class="eyebrow">The depth behind your results</span><h2>Expertise, connected.</h2></div><div class="department-grid">${departments.map((d,i)=>link('departments/'+slug(d),`<span class="dept-number">0${i+1}</span><h3>${d}</h3><span class="dept-arrow">↗</span>`)).join('')}</div></div></section><section class="business-feature"><img src="/assets/2149844649.jpg" alt="Scientist reviewing diagnostic images on a screen" width="1000" height="667" loading="lazy"><div class="business-feature-copy"><span class="eyebrow">Care beyond the individual</span><h2>For your people.<br>For what comes next.</h2><div class="business-links">${link('corporate-health','Corporate health <span>↗</span>')}${link('immigration-health','Immigration screening <span>↗</span>')}${link('business-partnership','Business partnerships <span>↗</span>')}</div></div></section><section class="branch-section section"><div class="wrap"><div class="branch-intro"><span class="eyebrow">Across Ghana</span><h2>A diagnostic chain.<br>A branch near you.</h2><p>Explore our locations in Accra, Kumasi and Bono & Ahafo. Confirm opening hours before your visit.</p></div><div class="branch-links">${branches.map((b,i)=>link('branches?branch='+encodeURIComponent(b),`<div><strong>${b}</strong><span>${i<2?'Accra':i<4?'Kumasi':'Bono & Ahafo'}</span></div><span>↗</span>`)).join('')}</div></div></section><section class="patient-guides section"><div class="wrap"><div class="section-head"><span class="eyebrow">A little more clarity</span><h2>Before your visit.</h2>${link('news','All patient guides ↗','textlink')}</div><div class="guide-grid">${[['preparing-for-a-test','Getting ready for your blood test.','18070','Scientist preparing a sample for analysis'],['understanding-your-report','Your report. Your next step.','2148960554','Laboratory scientist working at a computer']].map((p,i)=>`<a href="/news/${p[0]}"><div class="guide-photo"><img src="/assets/${p[2]}.jpg" alt="${p[3]}" loading="lazy" width="1700" height="603"></div><span class="eyebrow">Patient guide / 0${i+1}</span><h3>${p[1]} <span>↗</span></h3></a>`).join('')}</div></div></section>`}

const notice=t=>`<div class="notice">${t}</div>`;const testRows=(list=tests)=>list.map(t=>`<article class="test-row"><div>${link('tests/'+slug(t.name),`<h3>${t.name}</h3>`)}<p>${t.prep}</p></div><span class="tag">${t.dept}<br><br>Price: confirm with laboratory</span>${btn('book-appointment?service='+encodeURIComponent(t.name),'Select','blue')}</article>`).join('');let booking={service:'',branch:'',date:'',visit:'Branch visit'},step=0;let guideStep=0,guideAnswers=[];const field=(label,html)=>`<label for="${html.match(/id="([^"]+)/)?.[1]||''}">${label}</label>${html}`;function bookingForm(){const opts=(values,value)=>values.map(x=>`<option ${value===x?'selected':''}>${x}</option>`).join('');let body='';if(step===0)body=`<h3>What can we help you with?</h3>${field('Test or service',`<select id="service" required><option value="">Choose a service</option>${opts([...tests.map(t=>t.name),'Men’s screening','Women’s screening','Hypertension screening','Radiology','Corporate health'],booking.service)}</select>`)}${field('Visit type',`<select id="visit">${opts(['Branch visit','Home or office visit enquiry'],booking.visit)}</select>`)}`;if(step===1)body=`<h3>Pick your branch.</h3>${field('Preferred branch',`<select id="branch" required><option value="">Choose a branch</option>${opts(branches,booking.branch)}</select>`)}${field('Preferred date',`<input id="date" type="date" min="${new Date().toISOString().slice(0,10)}" required value="${booking.date}">`)}${notice('Dates are preferences. Availability and opening hours require confirmation.')}`;if(step===2)body=`<h3>Review your appointment plan.</h3><p><strong>Service:</strong> ${booking.service}<br><strong>Visit:</strong> ${booking.visit}<br><strong>Branch:</strong> ${booking.branch}<br><strong>Preferred date:</strong> ${booking.date}</p>${notice('This appointment plan is not sent to MMALABS. Contact your preferred branch to arrange a visit.')}<p>Save your plan and contact your preferred branch through an approved MMALABS channel.</p>`;$('#booking').innerHTML=`<div class="steps" aria-label="Step ${step+1} of 3">${[0,1,2].map(i=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><div class="eyebrow">Step ${step+1} / 3</div><form id="booking-form">${body}<div style="display:flex;gap:15px">${step?'<button type="button" class="btn" id="back">← Back</button>':''}<button class="btn blue" type="submit">${step===2?'Save appointment plan':'Continue'} <span>→</span></button></div></form>`;$('#back')?.addEventListener('click',()=>{step--;bookingForm()});$('#booking-form').onsubmit=e=>{e.preventDefault();if(step===0){booking.service=$('#service').value;booking.visit=$('#visit').value}if(step===1){booking.branch=$('#branch').value;booking.date=$('#date').value}if(step===2){const text=`MMALABS appointment plan — not a confirmed booking\nService: ${booking.service}\nVisit: ${booking.visit}\nBranch: ${booking.branch}\nPreferred date: ${booking.date}\nContact the laboratory to confirm availability and pricing.`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download='mmalabs-appointment-plan.txt';a.click();URL.revokeObjectURL(a.href);return}step++;bookingForm()}}
function guide(){const questions=[['Who is the screening for?',['Myself','A family member','My organisation']],['What do you want to explore?',['General health screening','A specific laboratory test','DNA testing','Imaging services']],['Where would you prefer to visit?',['Accra','Kumasi','Bono & Ahafo']]];if(guideStep===3){const dest=guideAnswers[0]==='My organisation'?'corporate-health':['nkwafit','tests','dna-testing','radiology'][questions[1][1].indexOf(guideAnswers[1])];$('#guide').innerHTML=`<div class="eyebrow">Your next step</div><h3>${pages[dest][0]}</h3><p>Explore the service and confirm suitability with the laboratory team.</p><p>Branches to explore: ${guideAnswers[2]==='Accra'?'Korle-Bu, Ofankor':guideAnswers[2]==='Kumasi'?'Kumasi Main':'Dormaa'}.</p>${btn(dest,'Explore service','blue')} ${btn('branches','View branches')}<br><button id="restart" class="btn">Start again</button>`;$('#restart').onclick=()=>{guideStep=0;guideAnswers=[];guide()};return}$('#guide').innerHTML=`<div class="eyebrow">Question ${guideStep+1} / 3</div><h3>${questions[guideStep][0]}</h3><div class="guide-options" style="margin-top:25px">${questions[guideStep][1].map(x=>`<button>${x} <span style="float:right">→</span></button>`).join('')}</div>`;document.querySelectorAll('.guide-options button').forEach(b=>b.onclick=()=>{guideAnswers.push(b.textContent.replace('→','').trim());guideStep++;guide()})}
const faqs=[['Do I need to fast before a test?','Preparation depends on your test. Ask the laboratory for instructions before your visit; do not change medicines without guidance from your clinician.'],['When will my results be ready?','Turnaround times depend on the test. Confirm the expected reporting time with your branch at sample collection.'],['Can I request a home visit?','Ask the team about collection coverage, availability and charges for your location.'],['How do I access my report?','Use the approved MMALABS secure report portal. The portal address must be verified before this website goes live.'],['What should I bring for DNA testing?','Confirm identification, consent and collection requirements directly with the DNA testing team.']];function inner(path){let data=pages[path];if(path.startsWith('news/'))data=path.endsWith('preparing-for-a-test')?['Getting ready for your blood test.','A few questions before your visit can help you prepare.']:['Your report. Your next step.','Discuss your results with a qualified healthcare professional.'];if(!data)data=['Page not found.','Use the navigation to find your next step.'];let body='';if(path==='tests')body=`<div class="searchbox"><input id="test-filter" aria-label="Search test menu" placeholder="Search by test, department or keyword"></div><p class="asset-note">Illustrative test catalogue. The approved test export, preparation instructions and prices are still required.</p><div id="test-rows">${testRows()}</div>`;else if(path.startsWith('tests/')){let t=tests.find(t=>slug(t.name)===path.split('/')[1]);body=t?`<div class="eyebrow">${t.dept}</div><h2>Plan your visit.</h2><p>Sample type: ${t.sample}</p><p>${t.prep}</p>${notice('Price, availability and turnaround time must be confirmed with the laboratory. This is an illustrative catalogue entry, pending clinical approval.')}${btn('book-appointment?service='+encodeURIComponent(t.name),'Choose this test','blue')}`:''}else if(path==='book-appointment')body='<div class="formbox" id="booking"></div>';else if(path==='help-me-choose')body='<div class="formbox" id="guide"></div>';else if(path==='nkwafit')body=`<div class="dark" style="padding:30px;border-radius:12px">${packages()}</div>${notice('Package contents, eligibility and prices require MMALABS approval. Confirm all details with the team before booking.')}`;else if(path==='view-report')body=`<div class="formbox"><div class="eyebrow">Secure report access</div><h2>Your results.<br>Kept private.</h2><p>Access your results through the official MMALABS report portal. Have the reference details provided by your branch ready.</p>${notice('The secure portal link has not yet been supplied. Use the secure report-access instructions provided by the branch that collected your sample. No patient data is collected here.')}${btn('contact','Get help with your report','blue')}</div>`;else if(path==='branches')body=`<div class="searchbox"><input id="branch-filter" aria-label="Filter branches" placeholder="Search Accra, Kumasi or a branch name"></div>${notice('Branch list comes from the supplied design brief and awaits confirmation. Addresses, phone numbers, coordinates and opening hours have not been supplied. Live distance and open-now status will be enabled once verified.')}<div id="branch-list">${branches.map((b,i)=>`<article class="test-row" data-branch="${b} ${i<2?'Accra':i<4?'Kumasi':'Bono Ahafo'}"><div><h3>${b}</h3><p>${i<2?'Accra':i<4?'Kumasi':'Bono & Ahafo'}</p><p>Address and hours: awaiting confirmation</p></div>${btn('book-appointment?branch='+encodeURIComponent(b),'Select branch','blue')}</article>`).join('')}</div><h3 style="margin-top:40px">Affiliate offices</h3><p>Takoradi · Sunyani · Tamale — service availability to be confirmed.</p>`;else if(path==='faqs')body=faqs.map(q=>`<details><summary>${q[0]}</summary><p>${q[1]}</p></details>`).join('');else if(path==='privacy')body=`<h2>Privacy notice</h2><p>This website does not request health records, identity documents or report credentials. Searches and filters are processed in your browser. Appointment requests and patient reports are not submitted or accessed through this website.</p><p>Outfit and Inter font files are loaded from Google Fonts. Your browser connects to Google to retrieve these fonts; system fonts are used if they are unavailable. For privacy enquiries, contact MMALABS.</p>`;else if(path==='terms')body=`<h2>Website terms</h2><p>Website content is for general information and does not replace advice from a qualified healthcare professional. Contact a branch to confirm service availability, appointment times, prices and opening hours before visiting.</p><p>Do not enter or share patient report credentials or sensitive health information through this website.</p>`;else if(path==='news')body=`<div class="business">${['preparing-for-a-test','understanding-your-report'].map((p,i)=>`<article><div class="eyebrow">Patient guide</div><h3>${i?'Your report. Your next step.':'Getting ready for your blood test.'}</h3><p>Practical information to help you plan your visit.</p>${link('news/'+p,'Read the guide ↗','textlink')}</article>`).join('')}</div>`;else if(path.startsWith('news/'))body=`<h2>${path.endsWith('preparing-for-a-test')?'Before your appointment':'After your report arrives'}</h2><p>${path.endsWith('preparing-for-a-test')?'Ask whether your test requires fasting and how long to fast. Confirm sample collection instructions with the laboratory. Tell the team about prescribed medicines, and ask your clinician before making any changes. Bring the referral or test request if you have one.':'Access your report only through an approved secure channel. Laboratory findings need context, including your symptoms and medical history. Arrange a discussion with your clinician to understand your results and any recommended next steps.'}</p>${btn('faqs','More patient questions','blue')}`;else if(path==='gallery')body=`<div class="photo-gallery">${galleryPhotos.map(([src,alt,caption])=>`<figure><img src="/assets/${src}" alt="${alt}" loading="lazy" width="1000" height="667"><figcaption>${caption}</figcaption></figure>`).join('')}</div>`;else if(['staff','careers','training','events'].includes(path))body=`<h2>${path==='staff'?'People make precision possible.':path==='careers'?'Bring your expertise.':path==='training'?'Learning connected to practice.':'Stay connected.'}</h2><p>${path==='staff'?'Meet team members across clinical, laboratory and support services.':path==='careers'?'Contact MMALABS to ask about current opportunities and application requirements.':path==='training'?'Contact MMALABS for course dates, eligibility, fees and registration details.':'Contact MMALABS for information about upcoming events and registration.'}</p>${notice('Contact MMALABS for current opportunities, team information, courses and events.')}${btn('contact','Make an enquiry','blue')}`;else if(path==='contact')body=`<div class="business"><article><div class="eyebrow">For patients</div><h3>Start with your branch.</h3><p>Choose the branch you would like to visit for test availability, opening hours and booking support.</p>${btn('branches','Find your branch','blue')}</article><article><div class="eyebrow">For organisations</div><h3>Connect your team.</h3><p>Explore corporate health, referral services and partnership enquiries.</p>${btn('business-partnership','Partnership enquiries','blue')}</article></div>${notice('Verified MMALABS phone numbers, email addresses and enquiry destinations must be supplied before contact requests can be enabled.')}`;else{let dept=path.startsWith('departments/');let relevant=dept?tests.filter(t=>slug(t.dept)===path.split('/')[1]):[];body=`<div class="dna"><div><div class="eyebrow">The MMALABS diagnostic chain</div><h2>${dept?'Specialist testing.<br>A clear next step.':path==='about'?'Care, connected.':path==='dna-testing'?'Confidence begins<br>with understanding.':'Let’s plan your next step.'}</h2><p>${path==='about'?'The MMALABS diagnostic chain connects laboratory testing, DNA, imaging and screening services across Ghana. Explore services, find a branch and plan your visit in one place.':path==='dna-testing'?'DNA testing begins with an informed conversation. Confirm the purpose of the test, consent requirements, identification and collection process with the team before arranging an appointment.':dept?'Explore department services and confirm the right test with your referring clinician and laboratory team.':'Tell the team what you need, confirm service availability and preparation, then choose the branch and appointment that work for you.'}</p>${btn('book-appointment','Plan an appointment','blue')}</div><img class="dna-photo" src="/assets/8926.jpg" width="1000" height="667" alt="Laboratory scientist inspecting a test sample" loading="lazy"></div>${relevant.length?`<div class="rows">${testRows(relevant)}</div>`:''}<div class="section-head" style="margin-top:70px"><h2>From enquiry<br>to your next step.</h2></div><div class="business"><article><div class="eyebrow">01 / Before your visit</div><h3>Confirm the details.</h3><p>Ask about availability, pricing, preparation and any consent or identification requirements.</p></article><article><div class="eyebrow">02 / At your appointment</div><h3>Know what comes next.</h3><p>Confirm collection instructions and expected reporting time with your selected branch.</p></article></div>${notice('Explore our services, find a branch or contact MMALABS to plan your visit.')}<h3 style="margin-top:40px">Explore the chain</h3><div class="departments" style="color:var(--blue)">${['tests','branches','faqs','view-report'].map(p=>link(p,`${pages[p][0]} ↗`)).join('')}</div>`}return `<section class="inner-hero"><div class="wrap"><div class="crumb">${link('','Home')} / ${data[0].replace(/\.$/,'')}</div><div class="eyebrow">MMALABS / ${path.split('/')[0].replaceAll('-',' ')}</div><h1 tabindex="-1">${data[0]}</h1><p>${data[1]}</p>${innerLinks(path)}</div></section><section class="content"><div class="wrap">${body}</div></section>`}
function bind(){const menu=$('.menu-btn');menu.onclick=()=>{const open=$('nav').classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')};$('#hero-search')?.addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();const list=tests.filter(t=>(t.name+' '+t.keywords+' '+t.dept).toLowerCase().includes(q));$('#search-results').innerHTML=q?(list.length?list.slice(0,4).map(t=>`<div class="result"><div>${link('tests/'+slug(t.name),`<strong>${t.name}</strong>`)}<p>Price: confirm with laboratory · ${t.prep}</p></div>${btn('book-appointment?service='+encodeURIComponent(t.name),'Book','blue')}</div>`).join(''):'<p>No matching tests. '+link('contact','Ask the laboratory →')+'</p>'):''});$('#test-filter')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();const list=tests.filter(t=>(t.name+' '+t.dept+' '+t.keywords).toLowerCase().includes(q));$('#test-rows').innerHTML=list.length?testRows(list):'<p>No matching tests. Contact the team to check availability.</p>'});$('#branch-filter')?.addEventListener('input',e=>document.querySelectorAll('[data-branch]').forEach(x=>x.hidden=!x.dataset.branch.toLowerCase().includes(e.target.value.toLowerCase())));document.querySelectorAll('[data-compare]').forEach(c=>c.onchange=()=>{const selected=[...document.querySelectorAll('[data-compare]:checked')].map(c=>Number(c.dataset.compare));const names=['Men’s health','Women’s health','Hypertension care'];$('#comparison').innerHTML=selected.length?`<div class="compare"><h3>Compare your screening options</h3><table><thead><tr><th>Package</th>${selected.map(i=>`<th>${names[i]}</th>`).join('')}</tr></thead><tbody>${['Included tests','Price','Preparation'].map(t=>`<tr><td>${t}</td>${selected.map(()=>'<td>Confirm with laboratory</td>').join('')}</tr>`).join('')}<tr><td>Next step</td>${selected.map(i=>`<td>${link('book-appointment?service='+encodeURIComponent(names[i]),'Plan appointment ↗')}</td>`).join('')}</tr></tbody></table></div>`:''});if($('#booking')){const q=new URLSearchParams(location.search);booking.service=q.get('service')||booking.service;booking.branch=q.get('branch')||booking.branch;bookingForm()}if($('#guide'))guide()}
function render(){const path=location.pathname.replace(/^\/|\/$/g,'');$('#main').innerHTML=path?inner(path):home();$('#foot').innerHTML=footer();document.title=path?(pages[path]?.[0]||'Patient guide')+' | MMALABS':'MMALABS — Ghana’s complete diagnostic chain';$('meta[name="description"]').content=pages[path]?.[1]||'Find your test, plan an appointment and explore MMALABS diagnostic services across Ghana.';bind();window.applySourceContent?.();initMotion()}
function innerLinks(path){let links=path.startsWith('departments/')?departments.map(d=>['departments/'+slug(d),d]):['tests','dna-testing','radiology','nkwafit'].includes(path)?[['tests','Laboratory testing'],['dna-testing','DNA testing'],['radiology','Imaging & radiology'],['nkwafit','Health screening']]:['about','staff','careers','training','gallery','events'].includes(path)?[['about','Our story'],['staff','Our people'],['careers','Careers']]:[['book-appointment','Book a test'],['view-report','View your report'],['branches','Find a branch']];return `<div class="inner-links">${links.map(([p,n])=>link(p,n+'<span>↗</span>')).join('')}</div>`}
menuGroups[1][1].splice(4,0,'spirometry');navNames.spirometry='Spirometry';
let motionCleanup=()=>{};
function initMotion(){motionCleanup();const path=location.pathname.replace(/^\/|\/$/g,'');document.body.dataset.page=path||'home';const menu=$('#site-menu');if(menu.open)menu.close();$('.menu-btn').onclick=()=>menu.showModal();$('.menu-close').onclick=()=>menu.close();const header=$('.site-header');const onScroll=()=>header.classList.toggle('scrolled',scrollY>90);window.addEventListener('scroll',onScroll,{passive:true});onScroll();document.querySelectorAll('nav a').forEach(a=>{if(a.pathname===location.pathname)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const quiet=matchMedia('(prefers-reduced-motion: reduce)').matches||navigator.connection?.saveData;let sectionObserver=null;const heroVideo=$('.hero-video'),pause=$('#hero-pause');let heroVideoCleanup=()=>{};if(heroVideo){const syncVideoControl=()=>{if(!pause)return;const isPaused=heroVideo.paused;pause.textContent=isPaused?'Play':'Pause';pause.setAttribute('aria-pressed',String(!isPaused));pause.setAttribute('aria-label',isPaused?'Play background video':'Pause background video')};const startVideo=()=>{heroVideo.play().catch(()=>{if(pause)pause.setAttribute('aria-label','Video could not start. Try again.')})};heroVideo.muted=true;heroVideo.addEventListener('play',syncVideoControl);heroVideo.addEventListener('pause',syncVideoControl);if(pause)pause.onclick=()=>heroVideo.paused?startVideo():heroVideo.pause();if(!quiet)startVideo();syncVideoControl();heroVideoCleanup=()=>{heroVideo.removeEventListener('play',syncVideoControl);heroVideo.removeEventListener('pause',syncVideoControl);heroVideo.pause();if(pause)pause.onclick=null}};const sections=[...document.querySelectorAll('#main > section')];const motionStyles=['zoom','rise','glide-left','glide-right'];const routeOffset=[...path].reduce((sum,char)=>sum+char.charCodeAt(0),0)%motionStyles.length;sections.forEach((e,index)=>{e.classList.add('scroll-depth',`scroll-depth--${motionStyles[(index+routeOffset)%motionStyles.length]}`)});const supportsViewTimeline=CSS.supports('animation-timeline','view()')&&CSS.supports('animation-range','entry 0% exit 100%');if(!supportsViewTimeline&&!matchMedia('(prefers-reduced-motion: reduce)').matches){sectionObserver=new IntersectionObserver(entries=>entries.forEach(entry=>entry.target.classList.toggle('is-in-view',entry.isIntersecting)),{threshold:.05});sections.forEach(e=>sectionObserver.observe(e))}motionCleanup=()=>{sectionObserver?.disconnect();heroVideoCleanup();window.removeEventListener('scroll',onScroll)};}

document.body.innerHTML=shell();render();document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||a.origin!==location.origin||a.hash||e.ctrlKey||e.metaKey||a.download)return;e.preventDefault();if(location.pathname+location.search===a.pathname+a.search){window.scrollTo(0,0);return}const c=$('#curtain');const title=pages[a.pathname.slice(1)]?.[0]||'MMALABS';c.textContent=title;c.classList.remove('go');void c.offsetWidth;c.classList.add('go');setTimeout(()=>{history.pushState({},'',a.href);render();window.scrollTo(0,0);(()=>{const h=$('h1');if(h){h.setAttribute('tabindex','-1');h.focus({preventScroll:true})}})()},400)});window.onpopstate=()=>{render();window.scrollTo(0,0)};window.addEventListener('scroll',()=>{const d=document.documentElement;$('#progress').style.width=(scrollY/(d.scrollHeight-innerHeight)*100)+'%'},{passive:true});
